// verse-validation.js

document.addEventListener("DOMContentLoaded", () => {
    const verseInput = document.getElementById("verseInput");

    if (verseInput) {
        verseInput.addEventListener("input", validateInput); // Bind validateInput on input event
    }
});

function validateInput() {
    let input = document.getElementById("verseInput").value.trim();
    console.log(`Input: ${input}`);

    if (input.length < 3) {
        disableShowButton();
        document.getElementById("verseInput").classList.remove("valid");
        return;
    }

    let isValid = isValidVerse(input);

    if (isValid) {
        enableShowButton();
        document.getElementById("verseInput").classList.add("valid");
    } else {
        disableShowButton();
        document.getElementById("verseInput").classList.remove("valid");
    }

    console.log(`isValid: ${isValid}`);
}

