function enableShowButton() {
    const button = document.getElementById("showButton");
    if (button) {
        button.disabled = false;
        button.classList.add("enabled");
        // console.log("enabled showbutton")
    }
}

function disableShowButton() {
    const button = document.getElementById("showButton");
    if (button) {
        button.disabled = true;
        button.classList.remove("enabled");
    }
}

function showVerse() {
    const input = document.getElementById("verseInput").value.trim();
    if (input !== "") {
        const [chapter, verse] = input.split(".");
        const pageType = document.body.getAttribute('data-page-type');

        if (pageType === "index") {
            // Redirect to index page
            window.location.href = `${chapter}/${verse}/index.html`;
        } else if (pageType === "verse") {
            // Redirect to verse page, modify URL accordingly
            window.location.href = `../../${chapter}/${verse}/index.html`;
        }
    }
}

document.getElementById("verseInput").addEventListener("keypress", function (event) {
    if (event.key === "Enter") {
        event.preventDefault();
        showVerse(); // Call the showVerse function when Enter is pressed
    }
});

